    public void PlaySoundEffect(int sfxid)
    {
        int start, end;
        bool repeat;
        PlaySoundEffect(sfxid, -1, 1, true, out start, out end, out repeat);

    }

    public byte[]? PlaySoundEffect(int sfxid, int note, int velocity, bool is8Bit, out int loopStart, out int loopEnd, out bool repeat)
    {
        loopStart = loopEnd = -1;
        repeat = false;
        if (sfxid <= 0)
        {
            return null;
        }

        if (sfxid >= SfxRecords.Length)
        {
            return null;
        }

        //if its in some sfx list return null


        var record = SfxRecords[sfxid];
        if (record == null || record.VabId == -2)
        {
            return null;
        }

        if (record.VabId == -1)
        {
            if (record.SeqNum != -1)
            {
                if ((record.Flags & 2) != 0)
                {
                    return null;//its already playing
                }

                //direct SoundBin playback does not route sequence SFX; runtime sequence playback lives in SoundManager.TryPlaySoundEffectSequence

                return null;//direct SoundBin helper still does not route sequence SFX
            }
            //check how many voices are already playing this sfx
            //return if its too many to play another one

            byte[]? wavetoreturn = null;
            for (var dex = 0; dex < record.NumTones; dex++)
            {
                var wave = PlaySfxInner(GlobalVabHeader, _globalSfxVabBodyBuff, record.ProgramNumber, record.ToneNumber + dex, note != -1 ? note : record.Note, is8Bit, out loopStart, out loopEnd, out repeat);
                if (wavetoreturn == null)
                {
                    wavetoreturn = wave;//return the first wave if its a series of tones
                }

                //register the voice info
                {

                }
            }

            return wavetoreturn;
        }
        else //its a mapvab
        {
            if (MapVabHeader == null)
            {
                return null;
            }

            //get a sfx in the group (refsfxchains through the group) that is for the currently loaded mapvab
            while (record.VabId != _mapVabIndex)
            {
                if (record.RefSfxId == 0)
                {
                    return null;//the vab requested is not loaded
                }

                if ((uint)record.RefSfxId >= (uint)SfxRecords.Length)
                {
                    return null;
                }

                record = SfxRecords[record.RefSfxId];
                if (record == null)
                {
                    return null;
                }
            }

            if (record.SeqNum != -1)
            {
                if ((record.Flags & 2) != 0)
                {
                    return null;//its already playing
                }

                //direct SoundBin playback does not route sequence SFX; runtime sequence playback lives in SoundManager.TryPlaySoundEffectSequence

                return null;//direct SoundBin helper still does not route sequence SFX
            }
            //check how many voices are already playing this sfx
            //return if its too many to play another one

            byte[]? wavetoreturn = null;
            for (var dex = 0; dex < record.NumTones; dex++)
            {
                var wave = PlaySfxInner(MapVabHeader, _mapSfxVabBodyBuff, record.ProgramNumber, record.ToneNumber + dex, note != -1 ? note : record.Note, is8Bit, out loopStart, out loopEnd, out repeat);
                if (wavetoreturn == null)
                {
                    wavetoreturn = wave;//return the first wave if its a series of tones
                }

                //register the voice info
                {

                }
            }

            return wavetoreturn;
        }

    }
    public byte[] PlaySfx(int sfx, int pitch, bool is8Bit, out int loopStart, out int loopEnd, out bool repeat)
    {
        return PlaySfxInner(sfx, GlobalVabHeader, _globalSfxVabBodyBuff, pitch, is8Bit, out loopStart, out loopEnd, out repeat);
    }

    public byte[] PlayMapSfx(int sfx, int pitch, bool is8Bit, out int loopStart, out int loopEnd, out bool repeat)
    {
        return PlaySfxInner(sfx, MapVabHeader, _mapSfxVabBodyBuff, pitch, is8Bit, out loopStart, out loopEnd, out repeat);
    }

    private byte[] PlaySfxInner(VabHeader header, byte[] bodybuff, int prognum, int tonenum, int note, bool is8Bit, out int loopStart, out int loopEnd, out bool repeat, int voiceId = -1, short rawPitchOverride = 0)
    {
        var attr = header.VagAttributes[prognum][tonenum];
        var vagIndex = attr.Vag > 0 ? attr.Vag - 1 : attr.Vag;
        var rawPitch = rawPitchOverride != 0 ? rawPitchOverride : CalculateToneRawPitch(attr, note);
        var sampleRate = ConvertRawPitchToSampleRate(rawPitch);
        return PlaySfxInner(vagIndex, header, bodybuff, sampleRate, is8Bit, out loopStart, out loopEnd, out repeat, voiceId, rawPitch);
    }

    private byte[] PlaySfxInner(int sfx, VabHeader header, byte[] bodybuff, int pitch, bool is8Bit, out int loopStart, out int loopEnd, out bool repeat, int voiceId = -1, short rawPitch = 0)
    {
        if (!TryGetVagBodyRange(header, sfx, out var pos, out var length))
        {
            loopStart = -1;
            loopEnd = -1;
            repeat = false;
            return [];
        }

        var blocks = length / 0x10;
        var bytespersample = 2;
        if (is8Bit)
        {
            bytespersample = 1;
        }

        byte[] buff = null!;
        int blockloopstart = -1;
        int blockloopend = -1;
        int decodedLength = 0;
        repeat = false;
        var cacheHit = !is8Bit && TryGetCachedDecodedVag16(header, sfx, out buff, out decodedLength, out blockloopstart, out blockloopend, out repeat);
        if (!cacheHit)
        {
            buff = new byte[blocks * SamplesPerBlock * bytespersample];
            decodedLength = DecodeAdpcm(bodybuff, pos, length, buff, is8Bit, out blockloopstart, out blockloopend, out repeat);
            if (!is8Bit)
            {
                CacheDecodedVag16(header, sfx, buff, decodedLength, blockloopstart, blockloopend, repeat);
            }
        }

        if ((blockloopend == -1 || blockloopstart == -1) && length != 0)
        {
            //this is not good, all samples should have loop points set, even if they arent used
            throw new Exception("no loop point set for sample");
        }
        loopStart = blockloopstart * SamplesPerBlock;//loops to start of block
        loopEnd = blockloopend * SamplesPerBlock + SamplesPerBlock - 1;//loops at end of block
        var encodedSampleRate = pitch > 0 ? pitch : 44100;
        if (_playbackBackend != null)
        {
            encodedSampleRate = ClampDesktopPcmSampleRate(encodedSampleRate);
        }

        short initialPitch = 0;
        if (_playbackBackend != null && pitch > 0)
        {
            var backendPitch = rawPitch;
            if (backendPitch == 0)
            {
                backendPitch = unchecked((short)((pitch * 0x1000 + 22050) / 44100));
            }

            initialPitch = backendPitch;
        }
        var ms = WriteWavFile(buff, 0, decodedLength, encodedSampleRate, is8Bit, _masterVolumeLeft, _masterVolumeRight);
        PlayWave(ms, voiceId, initialPitch, repeat, loopStart, loopEnd);

        return buff;
    }

    // JUSTIFICATION: PSX hardware adaptation only
    // RELATION: desktop mirror of already-uploaded SPU sample data; avoids re-decoding the same VAG on every key-on
    private static bool TryGetCachedDecodedVag16(VabHeader header, int vagIndex, out byte[] decodedPcm, out int decodedLength, out int loopStartBlock, out int loopEndBlock, out bool repeat)
    {
        decodedPcm = null!;
        decodedLength = 0;
        loopStartBlock = -1;
        loopEndBlock = -1;
        repeat = false;

        if ((uint)vagIndex >= (uint)header.DecodedPcm16Cache.Length)
        {
            return false;
        }

        var cachedPcm = header.DecodedPcm16Cache[vagIndex];
        if (cachedPcm == null || header.DecodedPcm16LengthCache[vagIndex] <= 0)
        {
            return false;
        }

        decodedPcm = cachedPcm;
        decodedLength = header.DecodedPcm16LengthCache[vagIndex];
        loopStartBlock = header.DecodedPcm16LoopStartBlockCache[vagIndex];
        loopEndBlock = header.DecodedPcm16LoopEndBlockCache[vagIndex];
        repeat = header.DecodedPcm16RepeatCache[vagIndex];
        return true;
    }

    // JUSTIFICATION: PSX hardware adaptation only
    // RELATION: desktop mirror of already-uploaded SPU sample data; avoids re-decoding the same VAG on every key-on
    private static void CacheDecodedVag16(VabHeader header, int vagIndex, byte[] decodedPcm, int decodedLength, int loopStartBlock, int loopEndBlock, bool repeat)
    {
        if ((uint)vagIndex >= (uint)header.DecodedPcm16Cache.Length || decodedLength <= 0)
        {
            return;
        }

        header.DecodedPcm16Cache[vagIndex] = decodedPcm;
        header.DecodedPcm16LengthCache[vagIndex] = decodedLength;
        header.DecodedPcm16LoopStartBlockCache[vagIndex] = loopStartBlock;
        header.DecodedPcm16LoopEndBlockCache[vagIndex] = loopEndBlock;
        header.DecodedPcm16RepeatCache[vagIndex] = repeat;
    }

    // JUSTIFICATION: PSX data layout bridge only
    // RELATION: mirrors Alundraportage VAB VAG_OffsetTable convention: entry 0 is pre-sample offset, entries 1.. are VAG sizes
    private static bool TryGetVagBodyRange(VabHeader header, int vagIndex, out int start, out int length)
    {
        start = 0;
        length = 0;

        if (vagIndex < 0 || vagIndex + 1 >= header.VagOffsetTable.Length)
        {
            return false;
        }

        start = header.VagOffsetTable[0] << 3;
        for (var vagOffsetIndex = 1; vagOffsetIndex <= vagIndex; vagOffsetIndex++)
        {
            start += header.VagOffsetTable[vagOffsetIndex] << 3;
        }

        length = header.VagOffsetTable[vagIndex + 1] << 3;
        return length > 0;
    }

    // JUSTIFICATION: PSX hardware adaptation only
    public byte[] PlayLoadedVabTone(int voiceId, VabHeader header, byte[] bodyBuffer, int programNumber, int toneNumber, int note, bool is8Bit, out int loopStart, out int loopEnd, out bool repeat, short rawPitchOverride = 0)
    {
        return PlaySfxInner(header, bodyBuffer, programNumber, toneNumber, note, is8Bit, out loopStart, out loopEnd, out repeat, voiceId, rawPitchOverride);
    }

    private System.Media.SoundPlayer _sp = null!;
    private Stream? _spStream;

    // JUSTIFICATION: PSX hardware adaptation only
    // RELATION: adapter for SpuSetCommonAttr master-volume observable contract
    public void SetMasterVolume(int volumeLeft, int volumeRight)
    {
        if (volumeLeft < 0)
        {
            volumeLeft = 0;
        }
        else if (volumeLeft > 0x7F)
        {
            volumeLeft = 0x7F;
        }

        if (volumeRight < 0)
        {
            volumeRight = 0;
        }
        else if (volumeRight > 0x7F)
        {
            volumeRight = 0x7F;
        }

        _masterVolumeLeft = volumeLeft;
        _masterVolumeRight = volumeRight;
    }

    public void PlayWave(Stream s, int voiceId = -1, short initialPitch = 0, bool shouldLoop = false, int loopStartSample = -1, int loopEndSample = -1)
    {
        if ((uint)voiceId < (uint)_voiceReleaseFramesRemaining.Length)
        {
            ClearVoiceEnvelopeState(voiceId);
        }

        if (_playbackBackend != null)
        {
            if (initialPitch != 0)
            {
                _playbackBackend.UpdateVoicePitch(voiceId, initialPitch);
            }

            if (_playbackBackend.Play(s, voiceId, shouldLoop, loopStartSample, loopEndSample))
            {
                s.Dispose();
                return;
            }
        }

        if ((uint)voiceId < (uint)_voicePlayers.Length)
        {
            var currentVoicePlayer = _voicePlayers[voiceId];
            if (currentVoicePlayer != null)
            {
                currentVoicePlayer.Stop();
            }

            var currentVoiceStream = _voiceStreams[voiceId];
            if (currentVoiceStream != null)
            {
                currentVoiceStream.Dispose();
            }

            var voicePlayer = new System.Media.SoundPlayer(s);
            _voiceStreams[voiceId] = s;
            _voicePlayers[voiceId] = voicePlayer;
        if (shouldLoop)
        {
            voicePlayer.PlayLooping();
        }
        else
        {
            voicePlayer.Play();
        }
            return;
        }

        if (_sp != null)
        {
            _sp.Stop();
        }

        if (_spStream != null)
        {
            _spStream.Dispose();
        }

        _spStream = s;
        _sp = new System.Media.SoundPlayer(s);
    if (shouldLoop)
    {
        _sp.PlayLooping();
    }
    else
    {
        _sp.Play();
    }
    }

    // JUSTIFICATION: PSX hardware adaptation only
    // RELATION: adapter for raw SPU per-voice left/right updates on already playing desktop voices
    public void UpdateTrackedVoiceStereoVolume(int voiceId, short volumeLeft, short volumeRight)
    {
        if ((uint)voiceId >= (uint)VoicesAreActive.Length)
        {
            return;
        }

        _voiceVolumeLeft[voiceId] = volumeLeft;
        _voiceVolumeRight[voiceId] = volumeRight;
        if (_voiceReleaseFramesRemaining[voiceId] > 0)
        {
            return;
        }

        ApplyTrackedVoiceAudibleVolume(voiceId);
    }

// JUSTIFICATION: PSX hardware adaptation only
// RELATION: adapter for raw SPU per-voice pitch updates on desktop tracked voices
public void UpdateTrackedVoicePitch(int voiceId, short pitch)
{
    if ((uint)voiceId >= (uint)VoicesAreActive.Length)
    {
        return;
    }

    _playbackBackend?.UpdateVoicePitch(voiceId, pitch);
}

// JUSTIFICATION: PSX hardware adaptation only
// RELATION: adapter for raw SPU per-voice reverb-word updates on desktop tracked voices
public void UpdateTrackedVoiceReverb(int voiceId, short reverb)
{
    if ((uint)voiceId >= (uint)VoicesAreActive.Length)
    {
        return;
    }

    _voiceReverbs[voiceId] = reverb;
    _playbackBackend?.UpdateVoiceReverb(voiceId, reverb != 0);
}

// JUSTIFICATION: PSX hardware adaptation only
// RELATION: adapter for raw SPU per-voice ADSR words on desktop tracked voices
public void UpdateTrackedVoiceAdsr(int voiceId, short adsr1, short adsr2)
{
    if ((uint)voiceId >= (uint)VoicesAreActive.Length)
    {
        return;
    }

    _voiceAdsr1[voiceId] = adsr1;
    _voiceAdsr2[voiceId] = adsr2;
}

// JUSTIFICATION: PSX hardware adaptation only
// RELATION: adapter for SPU key-off release envelope on desktop tracked voices
public void KeyOffTrackedVoice(int voiceId)
{
    if ((uint)voiceId >= (uint)VoicesAreActive.Length || VoicesAreActive[voiceId] == 0)
    {
        return;
    }

    var releaseFrames = CalculateReleaseFrameCount(_voiceAdsr2[voiceId]);
    _voiceReleaseFrameCount[voiceId] = releaseFrames;
    _voiceReleaseFramesRemaining[voiceId] = releaseFrames;
    _voiceReleaseStartEnvelopeLevels[voiceId] = GetTrackedVoiceEnvelopeLevel(voiceId);
    _voiceEnvelopeStages[voiceId] = VoiceEnvelopeStageRelease;
}

// JUSTIFICATION: PSX hardware adaptation only
// RELATION: adapter for the SpuSetReverb on/off observable contract on desktop
public void SetReverbEnabled(bool enabled)
{
    _reverbEnabled = enabled;
    _playbackBackend?.SetReverbEnabled(enabled);
}

// JUSTIFICATION: PSX hardware adaptation only
// RELATION: adapter for raw SpuSetReverbModeParam writes staged through g_spuReverbAttr2
public void UpdateReverbAttr(SpuReverbAttrPartial reverbAttr)
{
    _reverbAttr = reverbAttr;
    _playbackBackend?.SetReverbState(reverbAttr.Mode, reverbAttr.DepthLeft, reverbAttr.DepthRight);
}

    public static int DecodeAdpcm(byte[] adpcm, int pos, int len, byte[] pcm, bool is8Bit, out int loopstart, out int loopend, out bool looprepeat)
    {
        loopstart = loopend = -1;
        looprepeat = false;
        var pcmpos = 0;
        var filterTablePos = new[] { 0, 60, 115, 98, 122 };
        var filterTableNeg = new[] { 0, 0, -52, -55, -60 };

        var oldSmp = 0;
        var olderSmpl = 0;
        var numblocks = len / 16;
        var dpos = pos;
        var block = new AdpcmBlock();
        for (var dex = 0; dex < numblocks; dex++)
        {
            block.Fill(adpcm, dpos);
            if (block.IsLoopstart)
            {
                if (loopstart == -1)
                {
                    loopstart = dex;
                }
                else if (dex != loopend + 1)
                {
                    //this is a problem, why does this sample have multiple starts?
                    throw new Exception("sample has multiple start blocks.");
                }
            }
            if (block.IsLoopend)
            {
                if (loopend == -1)
                {
                    loopend = dex;
                    looprepeat = block.IsLooprepeat;
                }
                else if (dex != loopend + 1)
                {
                    //this is a problem, why does this sample have multiple ends?
                    throw new Exception("sample has multiple end blocks.");
                }
            }

            var shift = (byte)(block.ShiftFilter & 0xf);
            shift = shift > 12 ? (byte)9 : shift;
            var filterIndex = (byte)((block.ShiftFilter >> 4) & 0x7);
            filterIndex = filterIndex > 4 ? (byte)4 : filterIndex;
            var filterPos = filterTablePos[filterIndex];
            var filterNeg = filterTableNeg[filterIndex];

            for (var sdex = 0; sdex < SamplesPerBlock; sdex++)
            {
                var nib = block.Data[sdex / 2] >> (sdex % 2 * 4) & 0xf;
                var rawSample = (sbyte)(nib << 4) >> 4;
                var shiftedSample = rawSample << (12 - shift);
                var filteredSample = shiftedSample + (oldSmp * filterPos + olderSmpl * filterNeg + 32) / 64;
                var clampedSample = (short)(filteredSample < -0x8000 ? -0x8000 : filteredSample > 0x7FFF ? 0x7FFF : filteredSample);

                olderSmpl = oldSmp;
                oldSmp = clampedSample;

                if (is8Bit)
                {
                    int s = clampedSample;
                    var samplemax = 0x7fff;
                    var scaledmax = 0x7f;
                    s = (int)(s * ((float)scaledmax / samplemax));
                    pcm[pcmpos] = (byte)(sbyte)s;
                    pcmpos++;

                }
                else
                {
                    pcm[pcmpos + 1] = (byte)(clampedSample & 0xff);
                    pcm[pcmpos + 0] = (byte)((clampedSample & 0xff00) >> 8);
                    pcmpos += 2;
                }
            }

            dpos += 16;

            if (block.IsLoopend)
            {
                break;
            }
        }

        if (loopstart == -1)
        {
            loopstart = 0;
        }

        if (loopend == -1 && numblocks > 0)
        {
            loopend = numblocks - 1;
        }

        return pcmpos;
    }

    public class AdpcmBlock
    {
        public byte ShiftFilter;
        public byte Flags;//1=loop end,2=loop repeat,4=loop start
        public readonly byte[] Data = new byte[SamplesPerBlock / 2];
        public void Fill(byte[] adpcm, int pos)
        {
            ShiftFilter = adpcm[pos++];
            Flags = adpcm[pos++];
            Array.Copy(adpcm, pos, Data, 0, Data.Length);
        }

        public bool IsLoopstart { get { return (Flags & 4) != 0; } }
        public bool IsLoopend { get { return (Flags & 1) != 0; } }
        public bool IsLooprepeat { get { return (Flags & 2) != 0; } }
    }

    public static MemoryStream WriteWavFile(byte[] sampleData, int start, int length, int sampleRate, bool is8Bit, int masterVolumeLeft, int masterVolumeRight)
    {
        var ms = new MemoryStream();

        short numChannels = 1;
        short bps = 16;
        if (is8Bit)
        {
            bps = 8;
        }

        //8 bit should be chopped in half
        var numSamples = (int)(length / (bps / (float)8));
        var byteRate = (int)(sampleRate * numChannels * bps / (float)8);
        var blockAlign = (short)(numChannels * bps / (float)8);


        var subChunk1Size = 16;
        var subChunk2Size = numSamples * numChannels * bps / 8;

        var br = new BinaryWriter(ms);

        br.Write((byte)'R');
        br.Write((byte)'I');
        br.Write((byte)'F');
        br.Write((byte)'F');

        br.Write((int)(4 + 8 + subChunk1Size + 8 + subChunk2Size));

        br.Write((byte)'W');
        br.Write((byte)'A');
        br.Write((byte)'V');
        br.Write((byte)'E');


        br.Write((byte)'f');
        br.Write((byte)'m');
        br.Write((byte)'t');
        br.Write((byte)' ');
        br.Write(subChunk1Size);
        br.Write((short)1);//PCM
        br.Write(numChannels);
        br.Write(sampleRate);
        br.Write(byteRate);
        br.Write(blockAlign);
        br.Write(bps);


        br.Write((byte)'d');
        br.Write((byte)'a');

        // Mono desktop playback preserves the common-volume contract by folding left/right into one gain.
        var monoMasterVolume = (masterVolumeLeft + masterVolumeRight + 1) >> 1;
        if (monoMasterVolume < 0)
        {
            monoMasterVolume = 0;
        }
        else if (monoMasterVolume > 0x7F)
        {
            monoMasterVolume = 0x7F;
        }
        br.Write((byte)'t');
        br.Write((byte)'a');
        br.Write(subChunk2Size);



        for (var dex = start; dex < length - 1; dex += bps / 8)
        {
            if (is8Bit)
            {
                //br.Write(sampleData[dex + 0]);
                //br.Write(sampleData[dex + 1]);
                //br.Write((byte)0);
                int i = (sbyte)sampleData[dex];
                i = (i * monoMasterVolume) / 0x7F;
                i += 0x7f;

                if (i < 0)
                {
                    i = 0;
                }
                else if (i > 0xFF)
                {
                    i = 0xFF;
                }

                br.Write((byte)i);
            }
            else
            {
                var sample = (short)((sampleData[dex] << 8) | sampleData[dex + 1]);
                var scaledSample = (sample * monoMasterVolume) / 0x7F;

                if (scaledSample < short.MinValue)
                {
                    scaledSample = short.MinValue;
                }
                else if (scaledSample > short.MaxValue)
                {
                    scaledSample = short.MaxValue;
                }

                br.Write((byte)(scaledSample & 0xFF));
                br.Write((byte)((scaledSample >> 8) & 0xFF));
            }
        }

        ms.Position = 0;
        return ms;
    }

    public class VabHeader
    {
        public VabHeader(BinaryReader br)
        {
            Header = new VabHdr(br);
            for (var i = 0; i < 128; i++)
            {
                ProgAttributes[i] = new ProgAtr(br);
            }

            VagAttributes = new VagAtr[Header.Ps][];

            for (var programdex = 0; programdex < Header.Ps; programdex++)
            {
                //16 is max number of tones
                VagAttributes[programdex] = new VagAtr[16];
                for (var tonedex = 0; tonedex < 16; tonedex++)
                {
                    VagAttributes[programdex][tonedex] = new VagAtr(br);
                }
            }

            for (var dex = 0; dex < 256; dex++)
            {
                VagOffsetTable[dex] = br.ReadUInt16();//its bit shifted so needs to be << 3 when using the offset;
            }
        }

        public readonly VabHdr Header;
        public readonly ProgAtr[] ProgAttributes = new ProgAtr[128];
        public readonly VagAtr[][] VagAttributes;
        public readonly ushort[] VagOffsetTable = new ushort[256];
        public readonly byte[]?[] DecodedPcm16Cache = new byte[256][];
        public readonly int[] DecodedPcm16LengthCache = new int[256];
        public readonly int[] DecodedPcm16LoopStartBlockCache = new int[256];
        public readonly int[] DecodedPcm16LoopEndBlockCache = new int[256];
        public readonly bool[] DecodedPcm16RepeatCache = new bool[256];
        //int[] VagOffsetTable = new int[256];

        public class VabHdr//32 byte
        {
            public int Form;//always VABp
            public int Ver;//VAB file version number
            public int Id;//VAB id
            public uint Fsize;//VAB file size
            public ushort Reserved0;
            public readonly ushort Ps;//# of the programs in this bank
            public ushort Ts;//# of the tones in this bank
            public readonly ushort Vs;//# of the vags in this bank
            public byte Mvol;//master volume for this bank
            public byte Pan;//master panning for this bank
            public byte Attr1;//bank attributes1
            public byte Attr2;//bank attributes2
            public int Reserved1;
            public VabHdr(BinaryReader br)
            {
                Form = br.ReadInt32();
                Ver = br.ReadInt32();
                Id = br.ReadInt32();
                Fsize = br.ReadUInt32();
                Reserved0 = br.ReadUInt16();
                Ps = br.ReadUInt16();
                Ts = br.ReadUInt16();
                Vs = br.ReadUInt16();
                Mvol = br.ReadByte();
                Pan = br.ReadByte();
                Attr1 = br.ReadByte();
                Attr2 = br.ReadByte();
                Reserved1 = br.ReadInt32();
            }
        }

        public class ProgAtr//16 bytes
        {
            public readonly byte Tones;//# of tones
            public byte Mvol;//program volume
            public byte Prior;//program priority
            public byte Mode;//program mode
            public byte Mpan;//program pan
            public byte Reserved0;
            public short Attr;//program attribute
            public int Reserved1;
            public int Reserved2;
            public ProgAtr(BinaryReader br)
            {
                Tones = br.ReadByte();
                Mvol = br.ReadByte();
                Prior = br.ReadByte();
                Mode = br.ReadByte();
                Mpan = br.ReadByte();
                Reserved0 = br.ReadByte();
                Attr = br.ReadInt16();
                Reserved1 = br.ReadInt32();
                Reserved2 = br.ReadInt32();
            }
        }

        public class VagAtr//32 bytes
        {
            public byte Prior;//tone priority
            public byte Mode;//play mode
            public byte Vol;//tone volume
            public byte Pan;//tone panning
            public byte Center;//center note
            public byte Shift;//center note fine tune
            public byte Min;//minimum note limit
            public byte Max;//minimum note limit
            public byte VibW;//vibrate depth
            public byte VibT;//vibrate duration
            public byte PorW;//portamento depth
            public byte PorT;//portamento duration
            public byte Pbmin;//under pitch bend max
            public byte Pbmax;//upper pitch bend max
            public byte Reserved1;
            public byte Reserved2;
            public ushort Adsr1;//adsr1
            public ushort Adsr2;//adsr2
            public short Prog;//parent program
            public short Vag;//vag reference
            public readonly short[] Reserved = new short[4];
            public VagAtr(BinaryReader br)
            {
                Prior = br.ReadByte();
                Mode = br.ReadByte();
                Vol = br.ReadByte();
                Pan = br.ReadByte();
                Center = br.ReadByte();
                Shift = br.ReadByte();
                Min = br.ReadByte();
                Max = br.ReadByte();
                VibW = br.ReadByte();
                VibT = br.ReadByte();
                PorW = br.ReadByte();
                PorT = br.ReadByte();
                Pbmin = br.ReadByte();
                Pbmax = br.ReadByte();
                Reserved1 = br.ReadByte();
                Reserved2 = br.ReadByte();
                Adsr1 = br.ReadUInt16();
                Adsr2 = br.ReadUInt16();
                Prog = br.ReadInt16();
                Vag = br.ReadInt16();
                Reserved[0] = br.ReadInt16();
                Reserved[1] = br.ReadInt16();
                Reserved[2] = br.ReadInt16();
                Reserved[3] = br.ReadInt16();
            }
        }
    }

    public byte[] VoicesAreActive = new byte[24];
    public VoiceInfo VoiceInfo = new();

    // JUSTIFICATION: PSX hardware adaptation only
    // RELATION: adapter for Voice.status read by UpdateSoundVoicesState @ 0x8009311C
    public short GetTrackedVoiceStatus(int voiceId)
    {
        if ((uint)voiceId >= (uint)VoicesAreActive.Length || VoicesAreActive[voiceId] == 0)
        {
            return 0;
        }

        return unchecked((short)Math.Max(1, (0x7fff * GetTrackedVoiceEnvelopeLevel(voiceId)) / VoiceEnvelopeLevelMax));
    }

    public void AdvanceTrackedVoices()
    {
        for (var voiceId = 0; voiceId < VoicesAreActive.Length; voiceId++)
        {
            if (VoicesAreActive[voiceId] == 0)
            {
                continue;
            }

            if (_playbackBackend != null && !_playbackBackend.IsPlaying(voiceId))
            {
                StopTrackedVoice(voiceId);
                continue;
            }

            if (_voiceReleaseFramesRemaining[voiceId] > 0)
            {
                AdvanceTrackedVoiceRelease(voiceId);
                continue;
            }

            AdvanceTrackedVoiceEnvelope(voiceId);

            var framesRemaining = _voiceFramesRemaining[voiceId];
            if (framesRemaining < 0)
            {
                continue;
            }

            if (framesRemaining > 0)
            {
                framesRemaining--;
                _voiceFramesRemaining[voiceId] = framesRemaining;
            }

            if (framesRemaining == 0)
            {
                VoicesAreActive[voiceId] = 0;

                _playbackBackend?.Stop(voiceId);

                var currentVoicePlayer = _voicePlayers[voiceId];
                if (currentVoicePlayer != null)
                {
                    currentVoicePlayer.Stop();
                    _voicePlayers[voiceId] = null;
                }

                var currentVoiceStream = _voiceStreams[voiceId];
                if (currentVoiceStream != null)
                {
                    currentVoiceStream.Dispose();
                    _voiceStreams[voiceId] = null;
                }
            }
        }
    }

    public void StopTrackedVoice(int voiceId)
    {
        if ((uint)voiceId >= (uint)VoicesAreActive.Length)
        {
            return;
        }

        VoicesAreActive[voiceId] = 0;
        _voiceFramesRemaining[voiceId] = 0;
        ClearVoiceEnvelopeState(voiceId);
        _playbackBackend?.Stop(voiceId);

        var currentVoicePlayer = _voicePlayers[voiceId];
        if (currentVoicePlayer != null)
        {
            currentVoicePlayer.Stop();
            _voicePlayers[voiceId] = null;
        }

        var currentVoiceStream = _voiceStreams[voiceId];
        if (currentVoiceStream != null)
        {
            currentVoiceStream.Dispose();
            _voiceStreams[voiceId] = null;
        }
    }

    public void TrackVoicePlayback(bool useMapVab, int voiceId, int programNumber, int toneNumber, int note, VabHeader? explicitHeader = null, byte[]? explicitBodyBuffer = null)
    {
        if ((uint)voiceId >= (uint)VoicesAreActive.Length)
        {
            return;
        }

        VoicesAreActive[voiceId] = 1;
        StartVoiceEnvelope(voiceId);
        if (!TryGetToneFrameLifetime(useMapVab, programNumber, toneNumber, note, out var frameCount, out var repeat, explicitHeader, explicitBodyBuffer))
        {
            _voiceFramesRemaining[voiceId] = 1;
            return;
        }

        _voiceFramesRemaining[voiceId] = repeat ? -1 : Math.Max(frameCount, 1);
    }

    // JUSTIFICATION: PSX hardware adaptation only
    // RELATION: advances the desktop approximation of SPU ADSR key-off release
    private void AdvanceTrackedVoiceRelease(int voiceId)
    {
        var remaining = _voiceReleaseFramesRemaining[voiceId] - 1;
        if (remaining <= 0)
        {
            StopTrackedVoice(voiceId);
            return;
        }

        _voiceReleaseFramesRemaining[voiceId] = remaining;
        var frameCount = _voiceReleaseFrameCount[voiceId];
        if (frameCount <= 0)
        {
            StopTrackedVoice(voiceId);
            return;
        }

        _voiceEnvelopeLevels[voiceId] = (_voiceReleaseStartEnvelopeLevels[voiceId] * remaining) / frameCount;
        ApplyTrackedVoiceAudibleVolume(voiceId);
    }

    // JUSTIFICATION: PSX hardware adaptation only
    // RELATION: starts the desktop approximation of SPU ADSR attack/decay/sustain on key-on
    private void StartVoiceEnvelope(int voiceId)
    {
        ClearVoiceEnvelopeState(voiceId);
        _voiceEnvelopeSustainLevels[voiceId] = CalculateSustainLevel(_voiceAdsr1[voiceId]);
        var attackFrames = CalculateAttackFrameCount(_voiceAdsr1[voiceId]);
        if (attackFrames > 1)
        {
            _voiceEnvelopeStages[voiceId] = VoiceEnvelopeStageAttack;
            _voiceEnvelopeStageFrameCount[voiceId] = attackFrames;
            _voiceEnvelopeStageFramesRemaining[voiceId] = attackFrames;
            _voiceEnvelopeLevels[voiceId] = 0;
            ApplyTrackedVoiceAudibleVolume(voiceId);
            return;
        }

        _voiceEnvelopeLevels[voiceId] = VoiceEnvelopeLevelMax;
        EnterTrackedVoiceDecay(voiceId);
        ApplyTrackedVoiceAudibleVolume(voiceId);
    }

    // JUSTIFICATION: PSX hardware adaptation only
    // RELATION: advances attack/decay/sustain portions of the desktop ADSR approximation
    private void AdvanceTrackedVoiceEnvelope(int voiceId)
    {
        switch (_voiceEnvelopeStages[voiceId])
        {
            case VoiceEnvelopeStageAttack:
                AdvanceTrackedVoiceAttack(voiceId);
                break;

            case VoiceEnvelopeStageDecay:
                AdvanceTrackedVoiceDecay(voiceId);
                break;

            case VoiceEnvelopeStageSustain:
                AdvanceTrackedVoiceSustain(voiceId);
                break;
        }
    }

    // JUSTIFICATION: PSX hardware adaptation only
    // RELATION: advances the SPU ADSR2 sustain phase. On real hardware ENVX keeps stepping during
    // sustain: Sd=1 decreases toward zero (linear or pseudo-exponential), it does not hold the
    // sustain-entry level. Holding it constant left every sustained BGM voice at full envelope and
    // overdrove the desktop mix. Sustain-increase (Sd=0) keeps the previous hold behavior until a
    // case is proven to need it.
    private void AdvanceTrackedVoiceSustain(int voiceId)
    {
        var rawAdsr2 = unchecked((ushort)_voiceAdsr2[voiceId]);
        var sustainDecrease = (rawAdsr2 & 0x4000) != 0;
        var sustainRate = (rawAdsr2 >> 6) & 0x7f;
        if (!sustainDecrease || sustainRate == 0x7f)
        {
            return;
        }

        var level = _voiceSustainEnvelope31[voiceId];
        if (level <= 0)
        {
            return;
        }

        const int samplesPerFrame = 44100 / 60;
        var sustainExponential = (rawAdsr2 & 0x8000) != 0;
        var remainingSamples = samplesPerFrame;
        while (remainingSamples > 0 && level > 0)
        {
            uint rate;
            if (sustainExponential)
            {
                rate = GetExponentialSustainRate(sustainRate, level);
                if (rate == 0)
                {
                    break;
                }

                var rangeFloor = level & ~0xFFFFFFFL;
                var stepsToRangeFloor = ((level - rangeFloor) / rate) + 1;
                var steps = Math.Min(remainingSamples, stepsToRangeFloor);
                level -= rate * steps;
                remainingSamples -= (int)steps;
            }
            else
            {
                rate = GetAdsrRate(RoundToZero((sustainRate ^ 0x7f) - 0x0f) + 32);
                if (rate == 0)
                {
                    break;
                }

                level -= (long)rate * remainingSamples;
                remainingSamples = 0;
            }
        }

        if (level < 0)
        {
            level = 0;
        }

        _voiceSustainEnvelope31[voiceId] = level;
        _voiceEnvelopeLevels[voiceId] = (int)(level >> 16);
        ApplyTrackedVoiceAudibleVolume(voiceId);
    }

    // JUSTIFICATION: PSX hardware adaptation only
    // RELATION: mirrors the rate-table lookup used by Alundraportage DecodeADSR for the
    // pseudo-exponential sustain-decrease phase
    private static uint GetExponentialSustainRate(int sustainRate, long envelopeLevel)
    {
        var range = (int)((envelopeLevel >> 28) & 0x7);
        var offset = range switch
        {
            0 => 0,
            1 => 4,
            2 => 6,
            3 => 8,
            4 => 9,
            5 => 10,
            6 => 11,
            _ => 12,
        };

        return GetAdsrRate(RoundToZero((sustainRate ^ 0x7f) - 0x1b + offset) + 32);
    }

    // JUSTIFICATION: PSX hardware adaptation only
    // RELATION: advances the desktop attack ramp derived from SPU ADSR1
    private void AdvanceTrackedVoiceAttack(int voiceId)
    {
        var frameCount = _voiceEnvelopeStageFrameCount[voiceId];
        var remaining = _voiceEnvelopeStageFramesRemaining[voiceId] - 1;
        if (remaining <= 0 || frameCount <= 0)
        {
            _voiceEnvelopeLevels[voiceId] = VoiceEnvelopeLevelMax;
            EnterTrackedVoiceDecay(voiceId);
            ApplyTrackedVoiceAudibleVolume(voiceId);
            return;
        }

        _voiceEnvelopeStageFramesRemaining[voiceId] = remaining;
        _voiceEnvelopeLevels[voiceId] = (VoiceEnvelopeLevelMax * (frameCount - remaining)) / frameCount;
        ApplyTrackedVoiceAudibleVolume(voiceId);
    }

    // JUSTIFICATION: PSX hardware adaptation only
    // RELATION: enters the desktop decay ramp derived from SPU ADSR1
    private void EnterTrackedVoiceDecay(int voiceId)
    {
        var decayFrames = CalculateDecayFrameCount(_voiceAdsr1[voiceId]);
        var sustainLevel = _voiceEnvelopeSustainLevels[voiceId];
        if (decayFrames <= 1 || sustainLevel >= VoiceEnvelopeLevelMax)
        {
            _voiceEnvelopeStages[voiceId] = VoiceEnvelopeStageSustain;
            _voiceEnvelopeLevels[voiceId] = sustainLevel;
            _voiceSustainEnvelope31[voiceId] = (long)sustainLevel << 16;
            _voiceEnvelopeStageFrameCount[voiceId] = 0;
            _voiceEnvelopeStageFramesRemaining[voiceId] = 0;
            return;
        }

        _voiceEnvelopeStages[voiceId] = VoiceEnvelopeStageDecay;
        _voiceEnvelopeStageFrameCount[voiceId] = decayFrames;
        _voiceEnvelopeStageFramesRemaining[voiceId] = decayFrames;
    }

    // JUSTIFICATION: PSX hardware adaptation only
    // RELATION: advances the desktop decay ramp toward the SPU ADSR1 sustain level
    private void AdvanceTrackedVoiceDecay(int voiceId)
    {
        var frameCount = _voiceEnvelopeStageFrameCount[voiceId];
        var remaining = _voiceEnvelopeStageFramesRemaining[voiceId] - 1;
        var sustainLevel = _voiceEnvelopeSustainLevels[voiceId];
        if (remaining <= 0 || frameCount <= 0)
        {
            _voiceEnvelopeStages[voiceId] = VoiceEnvelopeStageSustain;
            _voiceEnvelopeLevels[voiceId] = sustainLevel;
            _voiceSustainEnvelope31[voiceId] = (long)sustainLevel << 16;
            ApplyTrackedVoiceAudibleVolume(voiceId);
            return;
        }

        _voiceEnvelopeStageFramesRemaining[voiceId] = remaining;
        _voiceEnvelopeLevels[voiceId] = sustainLevel + (((VoiceEnvelopeLevelMax - sustainLevel) * remaining) / frameCount);
        ApplyTrackedVoiceAudibleVolume(voiceId);
    }

    // JUSTIFICATION: PSX hardware adaptation only
    // RELATION: applies current desktop ADSR level to the raw SPU voice volume mirror
    private void ApplyTrackedVoiceAudibleVolume(int voiceId)
    {
        var envelopeLevel = GetTrackedVoiceEnvelopeLevel(voiceId);
        var volumeLeft = unchecked((short)((_voiceVolumeLeft[voiceId] * envelopeLevel) / VoiceEnvelopeLevelMax));
        var volumeRight = unchecked((short)((_voiceVolumeRight[voiceId] * envelopeLevel) / VoiceEnvelopeLevelMax));
        _playbackBackend?.UpdateVoiceStereoVolume(voiceId, volumeLeft, volumeRight);
    }

    // JUSTIFICATION: PSX hardware adaptation only
    // RELATION: returns full level until a desktop ADSR stage is active, matching prior backend behavior for untracked voices
    private int GetTrackedVoiceEnvelopeLevel(int voiceId)
    {
        return _voiceEnvelopeStages[voiceId] == VoiceEnvelopeStageOff
            ? VoiceEnvelopeLevelMax
            : _voiceEnvelopeLevels[voiceId];
    }

    // JUSTIFICATION: PSX hardware adaptation only
    // RELATION: clears the desktop ADSR/release state when the tracked voice is reused or hard-stopped
    private void ClearVoiceEnvelopeState(int voiceId)
    {
        _voiceEnvelopeStages[voiceId] = VoiceEnvelopeStageOff;
        _voiceEnvelopeLevels[voiceId] = VoiceEnvelopeLevelMax;
        _voiceSustainEnvelope31[voiceId] = (long)VoiceEnvelopeLevelMax << 16;
        _voiceEnvelopeStageFramesRemaining[voiceId] = 0;
        _voiceEnvelopeStageFrameCount[voiceId] = 0;
        _voiceEnvelopeSustainLevels[voiceId] = VoiceEnvelopeLevelMax;
        _voiceReleaseFramesRemaining[voiceId] = 0;
        _voiceReleaseFrameCount[voiceId] = 0;
        _voiceReleaseStartEnvelopeLevels[voiceId] = VoiceEnvelopeLevelMax;
    }

    // JUSTIFICATION: PSX hardware adaptation only
    // RELATION: decodes the SPU ADSR1 sustain nibble to the desktop envelope scale
    private static int CalculateSustainLevel(short adsr1)
    {
        var rawAdsr1 = unchecked((ushort)adsr1);
        var sustainLevel = ((rawAdsr1 & 0x000f) + 1) * 0x800;
        if (sustainLevel > VoiceEnvelopeLevelMax)
        {
            sustainLevel = VoiceEnvelopeLevelMax;
        }

        return sustainLevel;
    }

    // JUSTIFICATION: PSX hardware adaptation only
    // RELATION: derives attack duration from SPU ADSR1 using the Alundraportage/P.E.Op.S rate-table convention
    private static int CalculateAttackFrameCount(short adsr1)
    {
        const double sampleRate = 44100.0;
        const double frameRate = 60.0;
        const int maxEnvelopeFrames = 600;
        var rawAdsr1 = unchecked((ushort)adsr1);
        var attackMode = (rawAdsr1 & 0x8000) != 0;
        var attackRate = (rawAdsr1 & 0x7f00) >> 8;
        if ((attackRate ^ 0x7f) < 0x10)
        {
            attackRate = 0;
        }

        var rate = GetAdsrRate(RoundToZero((attackRate ^ 0x7f) - 0x10) + 32);
        if (rate == 0)
        {
            return 1;
        }

        double samples;
        if (!attackMode)
        {
            samples = Math.Ceiling(0x7fffffff / (double)rate);
        }
        else
        {
            samples = 0x60000000 / (double)rate;
            var remainder = 0x60000000 % rate;
            var rate2 = GetAdsrRate(RoundToZero((attackRate ^ 0x7f) - 0x18) + 32);
            if (rate2 != 0)
            {
                samples += Math.Ceiling(Math.Max(0, 0x1fffffff - remainder) / (double)rate2);
            }
        }

        return ClampEnvelopeFrames((int)Math.Ceiling(samples / sampleRate * frameRate), maxEnvelopeFrames);
    }

    // JUSTIFICATION: PSX hardware adaptation only
    // RELATION: derives decay duration from SPU ADSR1 using the Alundraportage/P.E.Op.S rate-table convention
    private static int CalculateDecayFrameCount(short adsr1)
    {
        const double sampleRate = 44100.0;
        const double frameRate = 60.0;
        const int maxEnvelopeFrames = 600;
        var rawAdsr1 = unchecked((ushort)adsr1);
        var decayRate = (rawAdsr1 & 0x00f0) >> 4;
        if (4 * (decayRate ^ 0x1f) < 0x18)
        {
            decayRate = 0;
        }

        var sustainLevel = CalculateSustainLevel(adsr1);
        var targetEnvelopeLevel = (long)((sustainLevel / (double)VoiceEnvelopeLevelMax) * 0x7fffffff);
        var envelopeLevel = 0x7fffffffL;
        var sampleCount = 0;
        var maxSamples = (int)(sampleRate * (maxEnvelopeFrames / frameRate));
        while (envelopeLevel > targetEnvelopeLevel && sampleCount < maxSamples)
        {
            var rate = GetExponentialDecayRate(decayRate, envelopeLevel);
            if (rate == 0)
            {
                break;
            }

            envelopeLevel -= rate;
            sampleCount++;
        }

        return ClampEnvelopeFrames((int)Math.Ceiling(sampleCount / sampleRate * frameRate), maxEnvelopeFrames);
    }

    // JUSTIFICATION: PSX hardware adaptation only
    // RELATION: mirrors the decay-rate lookup used by Alundraportage DecodeADSR
    private static uint GetExponentialDecayRate(int decayRate, long envelopeLevel)
    {
        var range = (int)((envelopeLevel >> 28) & 0x7);
        var offset = range switch
        {
            0 => 0,
            1 => 4,
            2 => 6,
            3 => 8,
            4 => 9,
            5 => 10,
            6 => 11,
            _ => 12,
        };

        return GetAdsrRate(RoundToZero((4 * (decayRate ^ 0x1f)) - 0x18 + offset) + 32);
    }

    // JUSTIFICATION: PSX hardware adaptation only
    // RELATION: clamps desktop ADSR durations to a practical frame range for tracked voices
    private static int ClampEnvelopeFrames(int frames, int maxEnvelopeFrames)
    {
        if (frames < 1)
        {
            return 1;
        }

        return Math.Min(frames, maxEnvelopeFrames);
    }

    // JUSTIFICATION: PSX hardware adaptation only
    // RELATION: derives a frame count from SPU ADSR2 release fields using the Alundraportage/P.E.Op.S rate-table convention
    private static int CalculateReleaseFrameCount(short adsr2)
    {
        const double sampleRate = 44100.0;
        const double frameRate = 60.0;
        const int maxReleaseFrames = 600;
        var rawAdsr2 = unchecked((ushort)adsr2);
        var releaseRate = rawAdsr2 & 0x001f;
        var releaseMode = (rawAdsr2 & 0x0020) != 0;
        double samples;

        if (!releaseMode)
        {
            var rate = GetAdsrRate(RoundToZero((4 * (releaseRate ^ 0x1f)) - 0x0c) + 32);
            samples = rate != 0 ? Math.Ceiling(0x7fffffff / (double)rate) : 0;
        }
        else
        {
            if ((releaseRate ^ 0x1f) * 4 < 0x18)
            {
                releaseRate = 0;
            }

            var envelopeLevel = 0x7fffffffL;
            var sampleCount = 0;
            var maxSamples = (int)(sampleRate * (maxReleaseFrames / frameRate));
            while (envelopeLevel > 0 && sampleCount < maxSamples)
            {
                var rate = GetExponentialReleaseRate(releaseRate, envelopeLevel);
                if (rate == 0)
                {
                    break;
                }

                envelopeLevel -= rate;
                sampleCount++;
            }

            samples = sampleCount;
        }

        var frames = (int)Math.Ceiling(samples / sampleRate * frameRate);
        if (frames < 1)
        {
            return 1;
        }

        return Math.Min(frames, maxReleaseFrames);
    }

    // JUSTIFICATION: PSX hardware adaptation only
    // RELATION: mirrors the rate-table lookup used by Alundraportage DecodeADSR
    private static uint GetExponentialReleaseRate(int releaseRate, long envelopeLevel)
    {
        var range = (int)((envelopeLevel >> 28) & 0x7);
        var offset = range switch
        {
            0 => 0,
            1 => 4,
            2 => 6,
            3 => 8,
            4 => 9,
            5 => 10,
            6 => 11,
            _ => 12,
        };

        return GetAdsrRate(RoundToZero((4 * (releaseRate ^ 0x1f)) - 0x18 + offset) + 32);
    }

    // JUSTIFICATION: PSX hardware adaptation only
    // RELATION: mirrors Alundraportage roundToZero for SPU ADSR rate-table indices
    private static int RoundToZero(int value)
    {
        return value < 0 ? 0 : value;
    }

    // JUSTIFICATION: PSX hardware adaptation only
    // RELATION: builds one entry of the Alundraportage/P.E.Op.S SPU ADSR rate table on demand
    private static uint GetAdsrRate(int tableIndex)
    {
        if (tableIndex < 32)
        {
            return 0;
        }

        if (tableIndex > 159)
        {
            tableIndex = 159;
        }

        uint rate = 3;
        uint rateStep = 1;
        var rateDivider = 0;
        uint currentValue = 0;
        for (var index = 32; index <= tableIndex; index++)
        {
            if (rate < 0x3fffffff)
            {
                rate += rateStep;
                rateDivider++;
                if (rateDivider == 5)
                {
                    rateDivider = 1;
                    rateStep *= 2;
                }
            }

            if (rate > 0x3fffffff)
            {
                rate = 0x3fffffff;
            }

            currentValue = rate;
        }

        return currentValue;
    }

    private bool TryGetToneFrameLifetime(bool useMapVab, int programNumber, int toneNumber, int note, out int frameCount, out bool repeat, VabHeader? explicitHeader = null, byte[]? explicitBodyBuffer = null)
    {
        frameCount = 0;
        repeat = false;

        VabHeader header;
        byte[] bodyBuffer;
        if (explicitHeader != null && explicitBodyBuffer != null)
        {
            header = explicitHeader;
            bodyBuffer = explicitBodyBuffer;
        }
        else if (!TryGetToneSource(useMapVab, out header, out bodyBuffer))
        {
            return false;
        }

        if ((uint)programNumber >= (uint)header.VagAttributes.Length || (uint)programNumber >= (uint)header.ProgAttributes.Length)
        {
            return false;
        }

        var tones = header.VagAttributes[programNumber];
        if ((uint)toneNumber >= (uint)tones.Length)
        {
            return false;
        }

        var tone = tones[toneNumber];
        var vagIndex = tone.Vag > 0 ? tone.Vag - 1 : tone.Vag;
        if ((uint)vagIndex >= (uint)header.VagOffsetTable.Length)
        {
            return false;
        }

        var sampleRate = CalculateToneSampleRate(tone, note);
        if (sampleRate <= 0)
        {
            return false;
        }

        if (!TryGetVagBodyRange(header, vagIndex, out var start, out var length))
        {
            return false;
        }

        var blocks = length / 0x10;
        if (blocks <= 0 || start < 0 || start + length > bodyBuffer.Length)
        {
            return false;
        }

        var usedBlocks = blocks;
        for (var blockIndex = 0; blockIndex < blocks; blockIndex++)
        {
            var flags = bodyBuffer[start + (blockIndex * 0x10) + 1];
            if ((flags & 0x01) != 0)
            {
                repeat = (flags & 0x02) != 0;
                usedBlocks = blockIndex + 1;
                break;
            }
        }

        var sampleCount = usedBlocks * SamplesPerBlock;
        frameCount = Math.Max(1, (int)Math.Ceiling(sampleCount * 60.0 / sampleRate));
        return true;
    }

    private bool TryGetToneSource(bool useMapVab, out VabHeader header, out byte[] bodyBuffer)
    {
        if (useMapVab)
        {
            if (_mapVabIndex < 0 || _mapSfxVabBodyBuff == null || _mapSfxVabHeaderBuff == null)
            {
                header = null!;
                bodyBuffer = null!;
                return false;
            }

            header = MapVabHeader;
            bodyBuffer = _mapSfxVabBodyBuff;
            return true;
        }

        header = GlobalVabHeader;
        bodyBuffer = _globalSfxVabBodyBuff;
        return true;
    }

    // JUSTIFICATION: PSX hardware adaptation only
    // RELATION: local raw SPU pitch derivation for SoundBin playback and tracked-voice lifetime
    private static short CalculateToneRawPitch(VabHeader.VagAtr tone, int note)
    {
        short fine = 0;
        var fineIndex = fine + tone.Shift;
        if (fineIndex < 0)
        {
            fineIndex += 7;
        }

        fineIndex >>= 3;

        var octaveCarry = 0;
        if (fineIndex >= 0x10)
        {
            octaveCarry = 1;
            fineIndex -= 0x10;
        }

        var noteDelta = octaveCarry + (note + 0x3c - tone.Center);
        var octaveShift = (noteDelta / 12) - 5;
        var pitch = s_voicePitchTable[((noteDelta % 12) << 4) + fineIndex];

        if (octaveShift > 0)
        {
            pitch = (ushort)(pitch << octaveShift);
        }
        else if (octaveShift < 0)
        {
            pitch = (ushort)(pitch >> -octaveShift);
        }

        return unchecked((short)pitch);
    }

    // JUSTIFICATION: PSX hardware adaptation only
    // RELATION: keep desktop PCM rates inside MonoGame's accepted DynamicSoundEffectInstance range; residual SPU pitch is applied by the backend.
    private static int ClampDesktopPcmSampleRate(int sampleRate)
    {
        if (sampleRate < 8000)
        {
            return 8000;
        }

        if (sampleRate > 48000)
        {
            return 48000;
        }

        return sampleRate;
    }

    // JUSTIFICATION: PSX hardware adaptation only
    // RELATION: convert raw SPU pitch units to desktop WAV sample-rate for timing and fallback playback
    private static int ConvertRawPitchToSampleRate(short rawPitch)
    {
        var pitch = unchecked((ushort)rawPitch);
        if (pitch == 0)
        {
            return 0;
        }

        return (int)(((uint)pitch * 44100u + 0x800u) >> 12);
    }

    private static int CalculateToneSampleRate(VabHeader.VagAtr tone, int note)
    {
        return ConvertRawPitchToSampleRate(CalculateToneRawPitch(tone, note));
    }

    public class SfxRecord
    {
        public SfxRecord(byte[] data)
        {
            using var br = new BinaryReader(new MemoryStream(data));
            VabId = br.ReadInt16();
            ProgramNumber = br.ReadInt16();
            ToneNumber = br.ReadInt16();
            Note = br.ReadInt16();
            Flags = br.ReadInt16();
            SeqNum = br.ReadInt16();
            RefSfxId = br.ReadInt16();
            Unknown1 = br.ReadInt16();
            MaxVoices = br.ReadInt16();
            Unknown2 = br.ReadInt16();
            NumTones = br.ReadInt16();
        }
        public readonly short VabId;
        public readonly short ProgramNumber;
        public readonly short ToneNumber;
        public readonly short Note;
        public readonly short Flags;//1=playing note, 2=playing seq
        public readonly short SeqNum;
        public readonly short RefSfxId;
        public readonly short Unknown1;
        public readonly short MaxVoices;
        public readonly short Unknown2;
        public readonly short NumTones;

    }
